package com.gregtech.gregtech.registry;
import com.gregtech.gregtech.block.BookShelfBlock;import com.gregtech.gregtech.content.book.BookShelfVariants;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.neoforged.neoforge.registries.DeferredHolder;
public final class GTBookShelves {private GTBookShelves(){}private static final java.util.Map<String,DeferredHolder<Block,BookShelfBlock>> ALL=new java.util.LinkedHashMap<>();public static java.util.Collection<DeferredHolder<Block,BookShelfBlock>> all(){return java.util.List.copyOf(ALL.values());}public static BookShelfBlock get(String id){return ALL.get(id).get();}public static void initialize(){for(var v:BookShelfVariants.all()){var b=GTBlocks.BLOCKS.register(v.path(),()->new BookShelfBlock(BlockBehaviour.Properties.of().mapColor(v.metal()?MapColor.METAL:MapColor.WOOD).strength(v.hardness(),v.resistance()).requiresCorrectToolForDrops().sound(v.metal()?SoundType.METAL:SoundType.WOOD),v));ALL.put(v.path(),b);GTBlocks.BLOCK_ITEMS.register(v.path(),()->new com.gregtech.gregtech.item.BookShelfBlockItem(b.get(),new net.minecraft.world.item.Item.Properties().stacksTo(16)));}}}
